import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 66 · holiday recipe: pecan pie (Google Trends 3/11: Thanksgiving dinner +300%, holiday dessert recipes, peanut/pecan rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, every Thanksgiving and every Christmas, there's one pie that goes first at my table. Not the pumpkin. Not the apple. The pecan. Dark, sweet, gooey filling, a crunchy layer of toasted pecans on top, and a flaky crust underneath. My husband used to cut his slice before the turkey was carved, and hide it on a saucer behind the bread basket.""",
   "pecan pie slice holiday table", "IT GOES FIRST")
sc("""But people tell me their pecan pie comes out runny, so it pours out when you cut it, or it's so sweet it makes your teeth ache, or the top burns while the middle is raw. So tonight I'm giving you my pecan pie, every step, and the five mistakes that ruin it. And stay with me, because the last one is how to tell when it's done, and it's the reason most pecan pies are runny.""",
   "runny pecan pie filling plate", "IT POURS OUT")

ch("A pie from the South")
sc("""Pecan pie is a Southern pie, honey. Pecan trees grow wild from Texas to Georgia, and Southern cooks made sweet pies with them for a hundred years. But it became famous all over America in the nineteen thirties, when the corn syrup company printed a recipe on the side of the bottle. After that, every grandmother in the country made the same pie.""",
   "pecan trees orchard south", "ON THE BOTTLE")
sc("""We didn't have pecans in Ohio when I was little. We had black walnuts. My mother made walnut pie, and it was good, but the first time I tasted real pecan pie was in nineteen fifty-two, at my Aunt Louise's house in Kentucky. I ate two slices and asked her for the recipe on the spot. She wrote it on the back of a church bulletin, and I still have it.""",
   "church bulletin handwritten recipe", "ON A CHURCH BULLETIN")
sc("""Aunt Louise's pie had two secrets that most recipes leave out. One is a little bit of salt, and the other is a splash of something brown. In a minute I'll tell you both. They're the reason her pie tasted rich instead of just sweet.""",
   "woman holding pecan pie kitchen", "TWO SECRETS")

sc("""Aunt Louise lived on a little farm outside Bowling Green, with three pecan trees in the yard that her grandfather planted. Every fall, the whole family picked up pecans off the ground in buckets, and in the evenings, they sat on the porch cracking them. A good night was two quarts of shelled pecans and sore thumbs for everybody. She sent us a box of them every Christmas until she was ninety.""",
   "family cracking pecans porch", "SORE THUMBS")

ch("What you need")
sc("""Here's what you need, honey, for one nine-inch pie. One unbaked pie crust, homemade or store-bought. Three eggs. One cup of dark or light corn syrup. A cup of packed brown sugar. A quarter cup of melted butter. One teaspoon of vanilla. Half a teaspoon of salt. And a cup and a half of pecan halves. That's it.""",
   "pecans corn syrup eggs brown sugar", "THE INGREDIENTS")
sc("""And Aunt Louise's first secret. The salt. Half a teaspoon. Mistake number one is leaving it out. Without salt, pecan pie is just sugar on top of sugar, and it makes your teeth ache. The salt balances the sweetness and makes the pecans taste nuttier. And her second secret, a tablespoon of bourbon or strong coffee in the filling. It makes it taste deep and rich.""",
   "salt shaker bourbon bottle", "SALT AND SOMETHING BROWN")

ch("The crust")
sc("""Step one, the crust. Fit it into a nine-inch pie pan, not deep dish, and crimp the edges high, because the filling bubbles up. Put it in the freezer for fifteen minutes while you make the filling. Mistake number two is a soggy bottom crust. The filling is very wet, and it soaks into a raw crust.""",
   "crimped pie crust pan", "CRIMP IT HIGH")
sc("""The fix is to bake the crust a little first. Line it with foil, fill it with dried beans or rice, and bake it at four hundred degrees for fifteen minutes. Then take out the foil and beans, and bake it five more minutes, just until the bottom looks dry. Then brush the inside with a little beaten egg white and bake one more minute. That seals it.""",
   "pie crust blind baking beans foil", "BAKE IT FIRST")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now turn the oven down to three hundred fifty, and let the crust cool a little while you make the filling. And put a baking sheet under the pie when it goes in. Pecan pie always bubbles over a little, and burnt sugar on the bottom of your oven smokes for a week.""",
   "pie on baking sheet oven", "A BAKING SHEET UNDER IT")

ch("The filling")
sc("""Step two. Toast the pecans first. Spread them on a baking sheet and bake them at three fifty for about seven minutes, until they smell warm and buttery. Mistake number three is raw pecans. They taste soft and a little bitter. Toasted pecans taste rich and crunchy. Chop about half of them coarsely for the inside, and keep the prettiest halves whole for the top.""",
   "toasted pecan halves baking sheet", "TOAST THE PECANS")
sc("""In a bowl, whisk the eggs just until they're broken up. Then whisk in the corn syrup, brown sugar, melted butter, vanilla, salt, and the bourbon or coffee. Mix it until smooth, but don't beat it hard. Mistake number four is beating in a lot of air. All those bubbles rise to the top in the oven and make a foamy, cracked crust on the pie.""",
   "whisking pecan pie filling bowl", "DON'T BEAT IN AIR")
sc("""Now scatter the chopped pecans in the bottom of the crust. Pour the filling over them slowly. Then arrange the whole pecan halves on top in circles, starting at the outside edge and working in, like the petals of a flower. They float, so they'll stay on top. Aunt Louise's pies looked like a sunflower, every single time.""",
   "arranging pecan halves on pie", "LIKE A SUNFLOWER")

sc("""And dark corn syrup or light, honey? Light corn syrup makes a sweet, golden, buttery pie. Dark corn syrup makes a deeper, darker pie that tastes a little like molasses. Aunt Louise used half and half. That's how I make it, and it's the best of both. Some cooks use cane syrup or honey instead, and that's wonderful too, if you have it.""",
   "light dark corn syrup bottles", "HALF AND HALF")

ch("Baking")
sc("""Step three. Bake the pie at three hundred fifty degrees for about fifty to sixty minutes. After about twenty-five minutes, if the edges of the crust are getting too brown, cover them with a ring of foil, or a pie shield. And if the top pecans are getting too dark, lay a loose sheet of foil over the whole pie.""",
   "pie crust shield foil oven", "PROTECT THE EDGES")
sc("""So far, salt and something brown, a crust baked first and sealed, toasted pecans, a gentle mix without air, and a sunflower on top. And now the most important part, the one I promised, how to tell when it's done. Mistake number five is taking it out too soon, when the middle is still liquid. That's why most pecan pies are runny.""",
   "pecan pie in oven baking", "THE MOST IMPORTANT PART")
sc("""Here's the test. Gently shake the pie. The edges should be set and puffed, and the very center, about the size of a silver dollar, should still jiggle a little, like gelatin. Not slosh like soup. If it sloshes, give it ten more minutes. Or use a thermometer in the center. It should read two hundred degrees. That's when the eggs have set the filling.""",
   "jiggling pie center test", "LIKE GELATIN")

ch("The cooling")
sc("""And here's the part nobody wants to hear, honey. Let it cool completely, at least three or four hours, on a rack, before you cut it. The filling keeps setting as it cools. If you cut it warm, it runs all over the plate, even if you baked it perfectly. Make it the day before Thanksgiving. It's even better the next day.""",
   "pecan pie cooling on rack", "LET IT COOL")
sc("""Pecan pie keeps at room temperature for one day, and then in the icebox for four days, covered. Let a cold slice sit out for twenty minutes, or warm it for ten seconds. And it freezes beautifully, sweetheart. Wrap it tight in plastic and foil, and freeze it for two months. Thaw it overnight in the icebox.""",
   "pecan pie wrapped foil freezer", "IT FREEZES BEAUTIFULLY")

sc("""And if it does come out runny, sweetheart, don't throw it away. Put it back in the oven for fifteen minutes, with foil over the top, and then let it cool completely, all the way, in the icebox overnight. Cold firms it up. Or spoon it over vanilla ice cream and call it pecan sundae. Nobody has ever complained about that at my table.""",
   "pecan pie over ice cream sundae", "PECAN SUNDAE")

ch("Serving")
sc("""Serve it with a big spoon of whipped cream, or a scoop of vanilla ice cream, and a cup of strong coffee to cut the sweetness. And cut it small, honey. It's rich. A thin slice is plenty for most people. Except my husband, who considered a quarter of a pie one serving.""",
   "pecan pie whipped cream coffee", "CUT IT SMALL")
sc("""And you can make it different ways. Add a cup of chocolate chips to the filling for a chocolate pecan pie, which my grandchildren call Derby pie. Or use maple syrup instead of corn syrup, which is the way they make it up north. Or make little pecan tassies, tiny pies in a mini muffin pan, for the Christmas cookie tray.""",
   "chocolate pecan pie slice", "DERBY PIE")

ch("Grandma's kitchen")
sc("""So one more time. Bake the crust first and seal it with egg white. Toast the pecans. Half a teaspoon of salt, and a splash of bourbon or coffee. Whisk gently, no air. Pecans in circles like a sunflower. Bake until only the center jiggles like gelatin, two hundred degrees. And let it cool for hours before you cut it. That's Aunt Louise's pecan pie, and it's never runny.""",
   "pecan pie holiday dessert table", "NEVER RUNNY")
sc("""Tell me in the comments, sweetheart. Pecan, pumpkin, or apple? Which pie goes first at your house? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "holiday pies table evening family", "WHICH PIE GOES FIRST?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma66", "Pecan Pie That NEVER Turns Out Runny (Grandma's 1952 Recipe)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Pecan pie, a Southern American dessert popularized nationally in the 1930s by recipes printed on corn syrup bottles.",
      "Recipe as written by Grandma Ruth: 1 pre-baked 9-inch crust, 3 eggs, 1 cup corn syrup, 1 cup brown sugar, 1/4 cup melted butter, 1 tsp vanilla, 1/2 tsp salt, 1 tbsp bourbon or coffee, 1 1/2 cups toasted pecans; 350 F for 50 to 60 minutes, to about 200 F in the center."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
